// SetDefaultTeam of the workspace to the related item.
// Sets o.R.DefaultTeam to related.
// Adds o to related.R.DefaultTeamWorkspaces.
func (o *Workspace) SetDefaultTeam(ctx context.Context, exec boil.ContextExecutor, insert bool, related *WorkspaceTeam) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"workspaces\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"default_team_id"}),
		strmangle.WhereClause("\"", "\"", 2, workspacePrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.DefaultTeamID, related.ID)
	if o.R == nil {
		o.R = &workspaceR{
			DefaultTeam: related,
		}
	} else {
		o.R.DefaultTeam = related
	}

	if related.R == nil {
		related.R = &workspaceTeamR{
			DefaultTeamWorkspaces: WorkspaceSlice{o},
		}
	} else {
		related.R.DefaultTeamWorkspaces = append(related.R.DefaultTeamWorkspaces, o)
	}

	return nil
}

// RemoveDefaultTeam relationship.
// Sets o.R.DefaultTeam to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Workspace) RemoveDefaultTeam(ctx context.Context, exec boil.ContextExecutor, related *WorkspaceTeam) error {
	var err error

	queries.SetScanner(&o.DefaultTeamID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("default_team_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.DefaultTeam = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.DefaultTeamWorkspaces {
		if queries.Equal(o.DefaultTeamID, ri.DefaultTeamID) {
			continue
		}

		ln := len(related.R.DefaultTeamWorkspaces)
		if ln > 1 && i < ln-1 {
			related.R.DefaultTeamWorkspaces[i] = related.R.DefaultTeamWorkspaces[ln-1]
		}
		related.R.DefaultTeamWorkspaces = related.R.DefaultTeamWorkspaces[:ln-1]
		break
	}
	return nil
}

